<?php /** @package Meridian_News */ ?><aside class="sidebar" aria-label="<?php esc_attr_e( 'Sidebar', 'meridian-news' ); ?>"><section class="newsletter"><p class="eyebrow"><?php esc_html_e( 'Weekly brief', 'meridian-news' ); ?></p><h2><?php esc_html_e( 'News worth your attention.', 'meridian-news' ); ?></h2><p><?php esc_html_e( 'A concise digest of the stories that matter. Add your preferred newsletter service form here.', 'meridian-news' ); ?></p></section><?php $author = get_users( array( 'number' => 1, 'orderby' => 'post_count', 'order' => 'DESC', 'has_published_posts' => array( 'post' ) ) ); if ( $author ) : $user = $author[0]; ?><section class="sidebar-author"><h2><?php esc_html_e( 'Our writers', 'meridian-news' ); ?></h2><?php echo get_avatar( $user->ID, 64 ); ?><h3><a href="<?php echo esc_url( get_author_posts_url( $user->ID ) ); ?>"><?php echo esc_html( $user->display_name ); ?></a></h3><p><?php echo esc_html( wp_trim_words( $user->description, 18 ) ); ?></p></section><?php endif; ?><section class="recent-posts"><h2><?php esc_html_e( 'Recent posts', 'meridian-news' ); ?></h2><ul><?php $recent = new WP_Query( array( 'posts_per_page' => 4, 'ignore_sticky_posts' => true ) ); while ( $recent->have_posts() ) : $recent->the_post(); ?><li><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date() ); ?></time></li><?php endwhile; wp_reset_postdata(); ?></ul></section><?php if ( is_active_sidebar( 'blog-sidebar' ) ) { dynamic_sidebar( 'blog-sidebar' ); } ?></aside>
